"use client";

import { cn } from "@/lib/utils";
import { MessageSquare, type LucideIcon, Music, Store } from "lucide-react";

interface ListItem {
  id: string;
  title: string;
  description?: string;
  icon: LucideIcon;
  iconStyle: string;
  time: string;
  badge?: {
    text: string;
    variant: "pink" | "indigo" | "orange";
  };
  starred?: boolean;
}

interface List01Props {
  items?: ListItem[];
  className?: string;
}

const iconStyles = {
  music:
    "bg-violet-400/10 text-violet-300 border-violet-400/15",
  store:
    "bg-indigo-400/10 text-indigo-300 border-indigo-400/15",
  message:
    "bg-emerald-400/10 text-emerald-400 border-emerald-400/15",
};

const ITEMS: ListItem[] = [
  {
    id: "1",
    title: "iMessage",
    description: 'John sent you a message: "Hey, what do you think about..."',
    icon: MessageSquare,
    iconStyle: "message",
    time: "now",
    badge: { text: "New", variant: "orange" },
  },
  {
    id: "2",
    title: "Apple Music",
    description: "Your Daily Mix is ready with 25 new songs",
    icon: Music,
    iconStyle: "music",
    time: "2 min ago",
    badge: { text: "Music", variant: "pink" },
  },
  {
    id: "3",
    title: "App Store",
    description: "Figma has been updated to version 2.0",
    icon: Store,
    iconStyle: "store",
    time: "5 min ago",
    badge: { text: "Update", variant: "indigo" },
  },
];

const badgeVariants = {
  pink: "bg-violet-400/10 text-violet-300 border-violet-400/10",
  indigo: "bg-indigo-400/10 text-indigo-300 border-indigo-400/10",
  orange: "bg-amber-400/10 text-amber-300 border-amber-400/10",
};

export default function List01({ items = ITEMS, className }: List01Props) {
  return (
    <div
      className={cn(
        "mx-auto w-full max-w-2xl rounded-2xl",
        "border border-white/[0.08]",
        "bg-[#09090B]/90 p-2",
        "backdrop-blur-xl",
        "shadow-[0_20px_60px_rgba(0,0,0,0.3)]",
        className,
      )}
    >
      <div className="space-y-1">
        {items.map((item) => (
          <div
            key={item.id}
            className={cn(
              "group flex items-start gap-4 rounded-xl p-4",
              "border border-transparent",
              "transition-all duration-200",
              "hover:border-white/[0.06] hover:bg-white/[0.025]",
            )}
          >
            <div
              className={cn(
                "flex size-10 shrink-0 items-center justify-center rounded-xl border",
                iconStyles[item.iconStyle as keyof typeof iconStyles],
              )}
            >
              <item.icon className="size-4.5" />
            </div>

            <div className="min-w-0 flex-1">
              <div className="flex flex-wrap items-center gap-2">
                <h3 className="text-sm font-medium text-zinc-100">
                  {item.title}
                </h3>

                {item.badge && (
                  <span
                    className={cn(
                      "rounded-full border px-2 py-0.5 text-[10px] font-medium",
                      badgeVariants[item.badge.variant],
                    )}
                  >
                    {item.badge.text}
                  </span>
                )}
              </div>

              {item.description && (
                <p className="mt-1 line-clamp-2 text-xs leading-5 text-zinc-500">
                  {item.description}
                </p>
              )}

              <span className="mt-2 block text-[10px] uppercase tracking-[0.08em] text-zinc-700">
                {item.time}
              </span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { Bell, Calendar, Mail, type LucideIcon } from "lucide-react";

interface ListItem {
  id: string;
  title: string;
  description?: string;
  icon: LucideIcon;
  time: string;
  unread?: boolean;
}

interface List02Props {
  items?: ListItem[];
  className?: string;
}

const ITEMS: ListItem[] = [
  {
    id: "1",
    title: "New email received",
    description: "Sarah sent you a project update",
    icon: Mail,
    time: "Just now",
    unread: true,
  },
  {
    id: "2",
    title: "Meeting reminder",
    description: "Team standup in 15 minutes",
    icon: Calendar,
    time: "15 min",
    unread: true,
  },
  {
    id: "3",
    title: "System notification",
    description: "Your backup completed successfully",
    icon: Bell,
    time: "1 hour ago",
    unread: false,
  },
];

export default function List02({ items = ITEMS, className }: List02Props) {
  return (
    <div
      className={cn(
        "mx-auto w-full max-w-md overflow-hidden rounded-2xl",
        "border border-white/[0.08]",
        "bg-[#0C0C0F]",
        "shadow-[0_20px_60px_rgba(0,0,0,0.3)]",
        className,
      )}
    >
      {items.map((item, index) => (
        <div
          key={item.id}
          className={cn(
            "group flex items-center gap-3 p-4",
            "transition-colors duration-200",
            "hover:bg-white/[0.025]",
            index !== items.length - 1 && "border-b border-white/[0.06]",
            item.unread && "bg-violet-400/[0.025]",
          )}
        >
          <div
            className={cn(
              "flex size-9 shrink-0 items-center justify-center rounded-xl border",
              item.unread
                ? "border-violet-400/20 bg-violet-400/10 text-violet-300"
                : "border-white/[0.06] bg-white/[0.025] text-zinc-500",
            )}
          >
            <item.icon className="size-4" />
          </div>

          <div className="min-w-0 flex-1">
            <div className="flex items-center gap-2">
              <h3
                className={cn(
                  "truncate text-sm",
                  item.unread
                    ? "font-medium text-zinc-100"
                    : "font-normal text-zinc-400",
                )}
              >
                {item.title}
              </h3>

              {item.unread && (
                <span className="size-1.5 shrink-0 rounded-full bg-violet-400" />
              )}
            </div>

            {item.description && (
              <p className="mt-0.5 truncate text-xs text-zinc-600">
                {item.description}
              </p>
            )}
          </div>

          <span className="shrink-0 text-[10px] text-zinc-700">
            {item.time}
          </span>
        </div>
      ))}
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { AlertCircle, Check, Clock } from "lucide-react";

interface ListItem {
  id: string;
  title: string;
  subtitle: string;
  status: "completed" | "pending" | "failed";
  progress?: number;
}

interface List03Props {
  items?: ListItem[];
  className?: string;
}

const statusConfig = {
  completed: {
    icon: Check,
    iconClass: "border-emerald-400/20 bg-emerald-400/10 text-emerald-400",
    text: "text-emerald-400",
    label: "Completed",
    bar: "bg-emerald-400",
  },
  pending: {
    icon: Clock,
    iconClass: "border-amber-400/20 bg-amber-400/10 text-amber-400",
    text: "text-amber-400",
    label: "Pending",
    bar: "bg-amber-400",
  },
  failed: {
    icon: AlertCircle,
    iconClass: "border-red-400/20 bg-red-400/10 text-red-400",
    text: "text-red-400",
    label: "Failed",
    bar: "bg-red-400",
  },
};

const ITEMS: ListItem[] = [
  {
    id: "1",
    title: "Database Migration",
    subtitle: "Production server",
    status: "completed",
    progress: 100,
  },
  {
    id: "2",
    title: "API Integration",
    subtitle: "Payment gateway",
    status: "pending",
    progress: 65,
  },
  {
    id: "3",
    title: "SSL Certificate",
    subtitle: "Domain renewal",
    status: "failed",
    progress: 0,
  },
];

export default function List03({ items = ITEMS, className }: List03Props) {
  return (
    <div
      className={cn(
        "mx-auto w-full max-w-lg overflow-hidden rounded-2xl",
        "border border-white/[0.08]",
        "bg-[#0C0C0F]",
        "shadow-[0_20px_60px_rgba(0,0,0,0.3)]",
        className,
      )}
    >
      {items.map((item, index) => {
        const config = statusConfig[item.status];
        const StatusIcon = config.icon;

        return (
          <div
            key={item.id}
            className={cn(
              "p-5 transition-colors hover:bg-white/[0.02]",
              index !== items.length - 1 && "border-b border-white/[0.06]",
            )}
          >
            <div className="flex items-center justify-between gap-4">
              <div className="flex min-w-0 items-center gap-3">
                <div
                  className={cn(
                    "flex size-9 shrink-0 items-center justify-center rounded-xl border",
                    config.iconClass,
                  )}
                >
                  <StatusIcon className="size-4" />
                </div>

                <div className="min-w-0">
                  <h3 className="truncate text-sm font-medium text-zinc-100">
                    {item.title}
                  </h3>
                  <p className="mt-0.5 truncate text-xs text-zinc-600">
                    {item.subtitle}
                  </p>
                </div>
              </div>

              <span
                className={cn(
                  "shrink-0 text-[10px] font-medium uppercase tracking-[0.08em]",
                  config.text,
                )}
              >
                {config.label}
              </span>
            </div>

            {item.progress !== undefined && (
              <div className="mt-4 h-1 overflow-hidden rounded-full bg-white/[0.06]">
                <div
                  className={cn(
                    "h-full rounded-full transition-all duration-500",
                    config.bar,
                  )}
                  style={{ width: `${item.progress}%` }}
                />
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { MoreHorizontal, Star } from "lucide-react";
import { useState } from "react";

interface ListItem {
  id: string;
  name: string;
  email: string;
  avatar: string;
  role: string;
  starred?: boolean;
}

interface List04Props {
  items?: ListItem[];
  className?: string;
}

const ITEMS: ListItem[] = [
  {
    id: "1",
    name: "Emma Wilson",
    email: "emma@company.com",
    avatar: "EW",
    role: "Product Designer",
    starred: true,
  },
  {
    id: "2",
    name: "James Chen",
    email: "james@company.com",
    avatar: "JC",
    role: "Senior Developer",
    starred: false,
  },
  {
    id: "3",
    name: "Sofia Martinez",
    email: "sofia@company.com",
    avatar: "SM",
    role: "Marketing Lead",
    starred: true,
  },
];

export default function List04({ items = ITEMS, className }: List04Props) {
  const [starredItems, setStarredItems] = useState<Record<string, boolean>>(
    items.reduce(
      (acc, item) => ({
        ...acc,
        [item.id]: item.starred ?? false,
      }),
      {},
    ),
  );

  const toggleStar = (id: string) => {
    setStarredItems((prev) => ({
      ...prev,
      [id]: !prev[id],
    }));
  };

  return (
    <div className={cn("mx-auto w-full max-w-xl space-y-2", className)}>
      {items.map((item, index) => (
        <div
          key={item.id}
          className={cn(
            "group flex items-center gap-3 rounded-2xl p-3.5",
            "border border-white/[0.07]",
            "bg-[#0C0C0F]",
            "transition-all duration-200",
            "hover:border-white/[0.12] hover:bg-white/[0.025]",
          )}
        >
          <div className="flex size-11 shrink-0 items-center justify-center rounded-full border border-violet-400/15 bg-violet-400/10 text-xs font-semibold text-violet-300">
            {item.avatar}
          </div>

          <div className="min-w-0 flex-1">
            <h3 className="truncate text-sm font-medium text-zinc-100">
              {item.name}
            </h3>
            <p className="truncate text-xs text-zinc-600">{item.email}</p>
          </div>

          <span className="hidden rounded-full border border-white/[0.07] bg-white/[0.025] px-3 py-1.5 text-[10px] font-medium text-zinc-500 sm:block">
            {item.role}
          </span>

          <div className="flex items-center gap-0.5">
            <button
              onClick={() => toggleStar(item.id)}
              aria-label={starredItems[item.id] ? "Unstar" : "Star"}
              className={cn(
                "flex size-8 items-center justify-center rounded-full transition-colors",
                starredItems[item.id]
                  ? "text-amber-400"
                  : "text-zinc-700 hover:bg-white/[0.05] hover:text-zinc-400",
              )}
            >
              <Star
                className="size-4"
                fill={starredItems[item.id] ? "currentColor" : "none"}
              />
            </button>

            <button
              aria-label={`More options for ${item.name}`}
              className="flex size-8 items-center justify-center rounded-full text-zinc-700 opacity-0 transition-all hover:bg-white/[0.05] hover:text-zinc-300 group-hover:opacity-100 focus-visible:opacity-100 focus-visible:outline-none"
            >
              <MoreHorizontal className="size-4" />
            </button>
          </div>
        </div>
      ))}
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import {
  Download,
  File,
  FileText,
  Film,
  Image,
  Trash2,
  type LucideIcon,
} from "lucide-react";

interface ListItem {
  id: string;
  name: string;
  size: string;
  type: "document" | "image" | "video" | "other";
  date: string;
}

interface List05Props {
  items?: ListItem[];
  className?: string;
}

const typeConfig: Record<
  string,
  { icon: LucideIcon; bg: string; color: string }
> = {
  document: {
    icon: FileText,
    bg: "bg-violet-400/10 border-violet-400/15",
    color: "text-violet-300",
  },
  image: {
    icon: Image,
    bg: "bg-indigo-400/10 border-indigo-400/15",
    color: "text-indigo-300",
  },
  video: {
    icon: Film,
    bg: "bg-amber-400/10 border-amber-400/15",
    color: "text-amber-300",
  },
  other: {
    icon: File,
    bg: "bg-white/[0.035] border-white/[0.06]",
    color: "text-zinc-500",
  },
};

const ITEMS: ListItem[] = [
  {
    id: "1",
    name: "Project_Proposal.pdf",
    size: "2.4 MB",
    type: "document",
    date: "Today",
  },
  {
    id: "2",
    name: "Design_Assets.zip",
    size: "156 MB",
    type: "image",
    date: "Yesterday",
  },
  {
    id: "3",
    name: "Demo_Recording.mp4",
    size: "89 MB",
    type: "video",
    date: "Mar 12",
  },
];

export default function List05({ items = ITEMS, className }: List05Props) {
  return (
    <div
      className={cn(
        "mx-auto w-full max-w-2xl overflow-hidden rounded-2xl",
        "border border-white/[0.08]",
        "bg-[#0C0C0F]",
        className,
      )}
    >
      <div className="border-b border-white/[0.06] px-5 py-4">
        <p className="text-[10px] uppercase tracking-[0.14em] text-zinc-600">
          Files
        </p>
        <h2 className="mt-1 text-sm font-medium text-zinc-100">
          Recent files
        </h2>
      </div>

      <div className="divide-y divide-white/[0.05]">
        {items.map((item) => {
          const config = typeConfig[item.type];
          const TypeIcon = config.icon;

          return (
            <div
              key={item.id}
              className="group flex items-center gap-4 p-4 transition-colors hover:bg-white/[0.025]"
            >
              <div
                className={cn(
                  "flex size-10 shrink-0 items-center justify-center rounded-xl border",
                  config.bg,
                )}
              >
                <TypeIcon className={cn("size-4.5", config.color)} />
              </div>

              <div className="min-w-0 flex-1">
                <h3 className="truncate text-sm font-medium text-zinc-200">
                  {item.name}
                </h3>

                <div className="mt-1 flex items-center gap-2">
                  <span className="text-[11px] text-zinc-600">
                    {item.size}
                  </span>

                  <span className="size-0.5 rounded-full bg-zinc-700" />

                  <span className="text-[11px] text-zinc-600">
                    {item.date}
                  </span>
                </div>
              </div>

              <div className="flex items-center gap-1 opacity-0 transition-opacity group-hover:opacity-100 focus-within:opacity-100">
                <button
                  aria-label={`Download ${item.name}`}
                  className="flex size-8 items-center justify-center rounded-full text-zinc-600 transition hover:bg-white/[0.06] hover:text-zinc-300"
                >
                  <Download className="size-4" />
                </button>

                <button
                  aria-label={`Delete ${item.name}`}
                  className="flex size-8 items-center justify-center rounded-full text-zinc-600 transition hover:bg-red-400/10 hover:text-red-400"
                >
                  <Trash2 className="size-4" />
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import {
  ArrowDownRight,
  ArrowUpRight,
  Minus,
} from "lucide-react";

interface ListItem {
  id: string;
  label: string;
  value: string;
  change: number;
  trend: "up" | "down" | "neutral";
}

interface List06Props {
  items?: ListItem[];
  className?: string;
}

const ITEMS: ListItem[] = [
  {
    id: "1",
    label: "Total Revenue",
    value: "$48,352",
    change: 12.5,
    trend: "up",
  },
  {
    id: "2",
    label: "Active Users",
    value: "2,847",
    change: -3.2,
    trend: "down",
  },
  {
    id: "3",
    label: "Conversion Rate",
    value: "3.24%",
    change: 0,
    trend: "neutral",
  },
  {
    id: "4",
    label: "Avg. Session",
    value: "4m 23s",
    change: 8.1,
    trend: "up",
  },
];

const trendConfig = {
  up: {
    icon: ArrowUpRight,
    color: "text-emerald-400",
    bg: "bg-emerald-400/10 border-emerald-400/10",
  },
  down: {
    icon: ArrowDownRight,
    color: "text-red-400",
    bg: "bg-red-400/10 border-red-400/10",
  },
  neutral: {
    icon: Minus,
    color: "text-zinc-500",
    bg: "bg-white/[0.035] border-white/[0.06]",
  },
};

export default function List06({ items = ITEMS, className }: List06Props) {
